import { Controller, Delete, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 2차 인증 대상 여부 설정값이 입력에 없으므로 기기 식별값을 보낸 경우에만 승인된 기기를 확인한다.
const SECOND_AUTH_REQUIRED = false;

@Controller('api/v1')
export class FnSfr04001Controller {
  @Post('/mobile-sessions')
  @HttpCode(200)
  async loginMobile(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const loginId = data['loginId'];
    const password = data['password'];
    const deviceIdentifier = data['deviceIdentifier'];
    if (typeof loginId !== 'string' || loginId.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '로그인 ID를 입력해 주세요.');
    }
    if (typeof password !== 'string' || password === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '비밀번호를 입력해 주세요.');
    }
    if (deviceIdentifier !== undefined && deviceIdentifier !== null && deviceIdentifier !== '') {
      if (typeof deviceIdentifier !== 'string' || deviceIdentifier.length > 200) {
        throw new ApiError(400, 'VALIDATION_FAILED', '인증기기 식별값은 200자 이내의 글자여야 합니다.');
      }
    }
    const device = typeof deviceIdentifier === 'string' && deviceIdentifier !== '' ? deviceIdentifier : null;
    return transaction(async (db) => {
      // 가정: 비밀번호는 DB의 crypt 해시 비교로 검증한다.
      const employees = await db.query(
        `SELECT employee_id AS "employeeId"
           FROM employee
          WHERE login_id = :loginId
            AND employment_status = '재직'
            AND password_hash IS NOT NULL
            AND password_hash = crypt(:password, password_hash)`,
        { loginId: loginId.trim(), password },
      );
      if (employees.length === 0) {
        throw new ApiError(422, 'INVALID_CREDENTIALS', '로그인 ID 또는 비밀번호가 일치하지 않습니다.');
      }
      const employeeId = employees[0]['employeeId'];
      if (SECOND_AUTH_REQUIRED && device === null) {
        throw new ApiError(422, 'SECOND_AUTH_FAILED', '2차 인증이 필요합니다. 승인된 인증기기로 인증해 주세요.');
      }
      if (device !== null) {
        const approved = await db.query(
          `SELECT auth_device_id AS "authDeviceId"
             FROM auth_device
            WHERE employee_id = CAST(:employeeId AS bigint)
              AND device_identifier = :device
              AND status = '승인'`,
          { employeeId, device },
        );
        if (approved.length === 0) {
          throw new ApiError(422, 'SECOND_AUTH_FAILED', '2차 인증에 실패했거나 승인되지 않은 인증기기입니다.');
        }
      }
      // 가정: 세션 토큰은 DB에서 난수로 발급한다.
      const tokens = await db.query(
        `SELECT replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '') AS "accessToken"`,
        {},
      );
      return { accessToken: tokens[0]['accessToken'] };
    });
  }

  @Delete('/mobile-sessions/current')
  async logoutMobile(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    return transaction(async () => {
      // 가정: 세션 저장소가 스펙에 없어 응답만 돌려준다.
      return {};
    });
  }
}

