import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Form, TextInput, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr04001Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [token, setToken] = useState('');
  const [history, setHistory] = useState<Row[]>([]);
  const [loginId, setLoginId] = useState('');
  const [password, setPassword] = useState('');
  const [deviceIdentifier, setDeviceIdentifier] = useState('');

  const addHistory = (kind: string) => {
    setHistory((prev) => [{ id: prev.length + 1, kind, result: '성공', at: new Date().toISOString() }, ...prev]);
  };

  const login = async () => {
    if (loginId.trim() === '') {
      throw new Error('로그인 ID를 입력해 주세요.');
    }
    if (password === '') {
      throw new Error('비밀번호를 입력해 주세요.');
    }
    const body: Row = { loginId: loginId.trim(), password };
    if (deviceIdentifier.trim() !== '') {
      body.deviceIdentifier = deviceIdentifier.trim();
    }
    const res = await call('POST', '/mobile-sessions', role, body);
    setToken(String(res.accessToken ?? ''));
    setPassword('');
    setOpen(false);
    addHistory('로그인');
    notify('로그인했습니다.');
  };

  const logout = async () => {
    await call('DELETE', '/mobile-sessions/current', role);
    setToken('');
    addHistory('로그아웃');
    notify('로그아웃했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>세션 현황</h2>
        <Tiles
          items={[
            ['로그인 상태', <Badge value={token ? '승인' : '대기'} />],
            ['처리 내역', history.length],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>로그인 내역</h2>
        <Band total={history.length}>
          {token === '' ? (
            <button type="button" onClick={() => setOpen(true)}>로그인</button>
          ) : (
            <button type="button" onClick={() => { logout().catch((e) => notify(String(e.message ?? e))); }}>로그아웃</button>
          )}
        </Band>
        <DataTable
          columns={[
            { key: 'kind', label: '구분' },
            { key: 'result', label: '결과', render: (r) => <Badge value={r.result} /> },
            { key: 'at', label: '일시', render: (r) => <DateText value={r.at} time /> },
          ]}
          rows={history}
          empty="처리한 내역이 없습니다."
        />
      </section>
      {open && (
        <Drawer title="모바일 로그인" onClose={() => setOpen(false)}>
          <Form onSubmit={login} submit="로그인">
            <Field label="로그인 ID" required>
              <TextInput value={loginId} onChange={setLoginId} />
            </Field>
            <Field label="비밀번호" required>
              <TextInput value={password} onChange={setPassword} />
            </Field>
            <Field label="인증기기 식별값" hint="2차 인증 대상이면 입력">
              <TextInput value={deviceIdentifier} onChange={setDeviceIdentifier} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
